-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Der englische Changelog enthält jetzt dieselben Zusammenfassungen und Stichpunkte zu Veröffentlichungen wie das Willkommensfenster und die Discord-Ankündigungen.","Changelog-Dateien sind für alle unterstützten Gebietsschemata verfügbar, mit bereits übersetztem Versionsverlauf und einer erhaltenen Kopie der älteren handgeschriebenen englischen Notizen.","Release-Prüfungen halten die Changelog-Dateien mit den kanonischen Hinweisen und Übersetzungen synchron."},["title"]="Einheitliche, mehrsprachige Changelogs"}},["version"]="5.16.7",["welcome"]="Lies dieselben QuestTogether-Versionshinweise im Spiel, auf Discord und in deiner bevorzugten Sprache in den Changelog-Dateien."},["esES"]={["sections"]={{["items"]={"El registro de cambios en inglés ahora comparte los mismos resúmenes de versión y puntos de la lista que la ventana de bienvenida y los anuncios de Discord.","Los archivos de registro de cambios están disponibles para todos los idiomas compatibles, con el historial de versiones traducido existente y una copia conservada de las antiguas notas en inglés escritas a mano.","Las comprobaciones de versión mantienen los archivos de registro de cambios sincronizados con las notas canónicas y las traducciones."},["title"]="Registros de cambios coherentes y multilingües"}},["version"]="5.16.7",["welcome"]="Lee las mismas notas de la versión de QuestTogether en el juego, en Discord y en tu idioma preferido en los archivos de registro de cambios."},["esMX"]={["sections"]={{["items"]={"El registro de cambios en inglés ahora comparte los mismos resúmenes de lanzamiento y puntos clave que la ventana de bienvenida y los anuncios de Discord.","Los archivos de registro de cambios están disponibles para todos los idiomas compatibles, con el historial de lanzamientos traducido existente y una copia preservada de las notas antiguas en inglés escritas manualmente.","Las comprobaciones de lanzamiento mantienen los archivos de registro de cambios sincronizados con las notas canónicas y las traducciones."},["title"]="Registros de cambios multilingües y coherentes"}},["version"]="5.16.7",["welcome"]="Lee las mismas notas de lanzamiento de QuestTogether dentro del juego, en Discord y en tu idioma preferido en los archivos de registro de cambios."},["frFR"]={["sections"]={{["items"]={"Le journal des modifications anglais reprend désormais les mêmes résumés de version et listes à puces que la fenêtre d’accueil et les annonces Discord.","Des fichiers de journal des modifications sont disponibles pour toutes les langues prises en charge, avec l’historique des versions traduit existant et une copie conservée des anciennes notes anglaises rédigées à la main.","Les vérifications de version maintiennent les fichiers du journal des modifications synchronisés avec les notes et traductions de référence."},["title"]="Journaux des modifications cohérents et multilingues"}},["version"]="5.16.7",["welcome"]="Lisez les mêmes notes de version de QuestTogether en jeu, sur Discord et dans votre langue préférée dans les fichiers du journal des modifications."},["itIT"]={["sections"]={{["items"]={"Il changelog inglese ora condivide gli stessi riepiloghi di rilascio e gli stessi punti elenco della finestra di benvenuto e degli annunci su Discord.","I file del changelog sono disponibili per tutte le lingue supportate, con la cronologia delle versioni tradotta esistente e una copia conservata delle vecchie note in inglese scritte a mano.","I controlli di rilascio mantengono i file del changelog sincronizzati con le note canoniche e le traduzioni."},["title"]="Changelog coerenti e multilingue"}},["version"]="5.16.7",["welcome"]="Leggi le stesse note di rilascio di QuestTogether in gioco, su Discord e nella tua lingua preferita nei file del changelog."},["koKR"]={["sections"]={{["items"]={"이제 영어 변경 내역은 환영 창 및 Discord 공지와 동일한 출시 요약과 글머리표 항목을 공유합니다.","지원되는 모든 로케일의 변경 내역 파일을 사용할 수 있으며, 기존 번역된 출시 기록과 이전에 직접 작성한 영어 노트의 보존 사본이 포함되어 있습니다.","출시 확인을 통해 변경 내역 파일이 표준 노트 및 번역과 동기화된 상태로 유지됩니다."},["title"]="일관된 다국어 변경 내역"}},["version"]="5.16.7",["welcome"]="게임 내, Discord, 변경 내역 파일에서 선호하는 언어로 동일한 QuestTogether 출시 노트를 읽을 수 있습니다."},["ptBR"]={["sections"]={{["items"]={"O changelog em inglês agora compartilha os mesmos resumos de lançamento e tópicos da janela de boas-vindas e dos anúncios no Discord.","Os arquivos de changelog estão disponíveis para todos os idiomas compatíveis, com o histórico de lançamentos traduzido existente e uma cópia preservada das notas antigas em inglês escritas manualmente.","As verificações de lançamento mantêm os arquivos de changelog sincronizados com as notas e traduções canônicas."},["title"]="Changelogs consistentes e multilíngues"}},["version"]="5.16.7",["welcome"]="Leia as mesmas notas de lançamento do QuestTogether dentro do jogo, no Discord e no seu idioma preferido nos arquivos de changelog."},["ruRU"]={["sections"]={{["items"]={"Английский журнал изменений теперь использует те же сводки выпусков и пункты списка, что и окно приветствия и объявления в Discord.","Файлы журнала изменений доступны для всех поддерживаемых локалей, с уже переведенной историей выпусков и сохраненной копией старых английских заметок, написанных вручную.","Проверки выпуска поддерживают синхронизацию файлов журнала изменений с каноническими примечаниями и переводами."},["title"]="Единые многоязычные журналы изменений"}},["version"]="5.16.7",["welcome"]="Читайте одни и те же примечания к выпуску QuestTogether в игре, в Discord и на предпочитаемом вами языке в файлах журнала изменений."},["zhCN"]={["sections"]={{["items"]={"英文更新日志现在与欢迎窗口和 Discord 公告共享相同的发布摘要和要点。","所有受支持的语言均提供更新日志文件，包含已翻译的既有发布历史，并保留了一份较早手写英文说明的副本。","发布检查会让更新日志文件与规范说明和翻译保持同步。"},["title"]="一致的多语言更新日志"}},["version"]="5.16.7",["welcome"]="在游戏内、Discord 上以及更新日志文件中，用你偏好的语言阅读相同的 QuestTogether 发布说明。"},["zhTW"]={["sections"]={{["items"]={"英文更新日誌現在與歡迎視窗和 Discord 公告共用相同的版本摘要與項目符號內容。","所有支援的語系皆提供更新日誌檔案，包含既有已翻譯的版本歷史，並保留一份較舊的手寫英文說明副本。","版本檢查會讓更新日誌檔案與標準說明及翻譯保持同步。"},["title"]="一致的多語言更新日誌"}},["version"]="5.16.7",["welcome"]="在遊戲內、Discord，以及你偏好語言的更新日誌檔案中，閱讀相同的 QuestTogether 版本說明。"}}
